import { mkdir, cp, rm, writeFile, readFile, access } from 'node:fs/promises';
import { join, basename } from 'node:path';
import { SEO_CONFIG, publishedRecords, recordBySlug } from '../src/editorial/content.mjs';
import { notableProfiles } from '../src/notables.mjs';
import { content } from '../src/content.mjs';
import { renderHistoryPage, founders, renderFounderCard } from '../src/editorial/founders-content.mjs'
import { chapterRecords, chapterCategories, chapterSource, chapterSourceNote } from '../src/editorial/chapters-data.mjs';;

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
// Public pages explain the historical subject first. Source limitations remain
// available in the source trail, rather than becoming the page's main voice.
const publicCopy = value => String(value ?? '')
  .replaceAll('research lead', 'historical reference')
  .replaceAll('Research lead', 'Historical reference')
  .replaceAll('This page provides', 'This page offers')
  .replaceAll('source-aware', 'grounded in the available sources')
  .replaceAll('Source-Aware', 'Grounded in the Available Sources')
  .replaceAll('Document Publication Is Grounded in the Available Sources', 'Documents Need Their Own Context');
const abs = path => `${SEO_CONFIG.origin}${path}`;

// Optional portrait handoff: publish only exact approved records whose mapped
// public_copy_path exists. The manifest uses `assets`, `status`, and
// `public_copy_path`; do not infer a filename from a profile name.
const portraitMap = new Map();
try {
  const raw = JSON.parse(await readFile('assets/research/personality-portraits/manifest.json', 'utf8'));
  const records = Array.isArray(raw) ? raw : (raw.assets || raw.profiles || raw.records || raw.portraits || []);
  for (const record of records) {
    const id = record.id || record.profileId || record.slug;
    const approved = String(record.status || '').toLowerCase() === 'approved' && record.permission_needed !== true;
    const relative = record.public_copy_path;
    const file = relative ? basename(relative) : '';
    if (!id || !approved || !relative || !/^[a-z0-9][a-z0-9._-]*\.webp$/i.test(file)) continue;
    const normalized = relative.replaceAll('\\', '/').replace(/^\.\//, '');
    const servedPath = `/${normalized}`;
    try { await access(join('.', normalized)); portraitMap.set(id, servedPath); } catch { /* exact approved asset is absent */ }
  }
} catch { /* no portrait handoff; initials remain the honest fallback */ }
const portraitFor = profile => portraitMap.get(profile.id);
const portraitMarkup = (profile, className = 'personality-portrait') => portraitFor(profile)
  ? `<img class="${className}" src="${portraitFor(profile)}" alt="Portrait of ${esc(profile.name)}" width="800" height="1000" style="height:auto" loading="lazy" decoding="async">`
  : `<div class="${className} personality-monogram" aria-label="Portrait unavailable for ${esc(profile.name)}">${esc(profile.initials)}</div>`;
const nav = `<header class="editorial-header"><a class="editorial-brand" href="/" aria-label="Tau Gamma Phi home"><img src="/src/assets/brand/seal-512.png" alt="Tau Gamma Phi seal" width="44" height="44" decoding="async"><span><strong>TAU GAMMA PHI</strong><small>Triskelions’ Grand Fraternity</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="editorial-nav">Menu</button><nav id="editorial-nav" aria-label="Primary navigation"><a href="/about/">About</a><a href="/history/">History</a><a href="/councils/">Councils</a><a href="/chapters/">Chapters</a><a href="/global/">Global</a><a href="/service/">Service</a><a href="/videos/">Videos</a><a href="/archive/">Archive</a><a href="/news/">News</a><details><summary>More</summary><div class="nav-dropdown"><a href="/founding-fathers/">Founding Fathers</a><a href="/notable-triskelions/">Notable Triskelions</a><a href="/sources/">Sources</a><a href="/contribute/">Contribute</a><a href="/contact/">Contact</a></div></details></nav><script type="module">import { initHeaderNavigation } from '/src/header-navigation.mjs'; initHeaderNavigation({ root: document.querySelector('#editorial-nav'), menuToggle: '.editorial-header .menu-toggle' });</script></header>`;
const footer = `<footer class="editorial-footer"><div><strong>Tau Gamma Phi</strong><p>Preserving the history, service, people, councils, chapters, and stories that continue to shape the brotherhood across generations.</p></div><nav aria-label="Footer"><a href="/about/">About</a><a href="/history/">History</a><a href="/councils/">Councils</a><a href="/chapters/">Chapters</a><a href="/global/">Global archive</a><a href="/service/">Service</a><a href="/videos/">Videos</a><a href="/archive/">Archive</a><a href="/news/">News</a><a href="/sources/">Sources</a><a href="/contribute/">Contribute</a><a href="/corrections/">Corrections</a><a href="/contact/">Contact</a><a href="/privacy/">Privacy</a><a href="/accessibility/">Accessibility</a></nav></footer>`;
const breadcrumb = items => `<nav class="breadcrumbs" aria-label="Breadcrumb"><ol>${items.map((item, i) => `<li>${i === items.length - 1 ? `<span aria-current="page">${esc(item.label)}</span>` : `<a href="${esc(item.href)}">${esc(item.label)}</a>`}</li>`).join('')}</ol></nav>`;
const head = ({ title, description, path, type='WebPage', noindex=false }) => `${nav}<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · Tau Gamma Phi archive</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${abs(path)}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${abs(path)}"><meta property="og:type" content="${type === 'CollectionPage' ? 'website' : 'article'}"><meta name="theme-color" content="#0a0d10"><meta name="twitter:card" content="summary_large_image"><meta property="og:image" content="https://triskelion-de-zamboanga-digital-hub.vercel.app/src/assets/editorial/tau-gamma-phi-records-cover.webp">${noindex ? '<meta name="robots" content="noindex,follow">' : ''}<link rel="stylesheet" href="/src/editorial/editorial.css"><link rel="stylesheet" href="/src/editorial/founders.css"><link rel="icon" href="/src/assets/brand/favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="32x32" href="/src/assets/brand/favicon-32.png"><link rel="apple-touch-icon" sizes="180x180" href="/src/assets/brand/seal-180.png"></head>`;
const schemas = ({ title, description, path, type='WebPage', breadcrumbs, record }) => {
  const base = { '@context':'https://schema.org', '@type': type, name:title, description, url:abs(path), isPartOf:{ '@type':'WebSite', name:SEO_CONFIG.siteName, url:abs('/') }, breadcrumb:{ '@type':'BreadcrumbList', itemListElement:breadcrumbs.map((item, position)=>({ '@type':'ListItem', position:position+1, name:item.label, item:abs(item.href) })) } };
  if (record?.eligibleForArticleSchema) Object.assign(base, { headline:record.title, image:abs(record.cover.src), author:{ '@type':'Organization', name:SEO_CONFIG.siteName }, publisher:{ '@type':'Organization', name:SEO_CONFIG.siteName }, dateModified:record.researchDate, inLanguage:'en' });
  return `<script type="application/ld+json">${JSON.stringify(base)}</script>`;
};

// Decorative abstract banner per route type. These are original Pillow-generated
// WebP graphics derived from the official seal geometry and the approved palette.
// They are decorative only: no text, portraits, documents, or invented insignia,
// and they must never be read as evidence of an event, chapter, person, or record.
const bannerFor = path => {
  if (path === '/') return '';
  const category = /^\/(regions|councils|chapters|videos|references)\//.test(path)
    || ['/regions/','/councils/','/chapters/','/videos/','/references/'].includes(path);
  const wide = category
    ? { base: '/src/assets/context/editorial-category-header-600.webp',
        srcset: '/src/assets/context/editorial-category-header-600.webp 600w, /src/assets/context/editorial-category-header-1200.webp 1200w',
        sizes: '(max-width: 720px) 100vw, 1200px', w: 1200, h: 720 }
    : { base: '/src/assets/context/editorial-section-banner-800.webp',
        srcset: '/src/assets/context/editorial-section-banner-800.webp 800w, /src/assets/context/editorial-section-banner-1600.webp 1600w',
        sizes: '(max-width: 720px) 100vw, 1600px', w: 1600, h: 640 };
  return `<div class="editorial-banner" aria-hidden="true"><img src="${wide.base}" srcset="${wide.srcset}" sizes="${wide.sizes}" width="${wide.w}" height="${wide.h}" alt="" loading="lazy" decoding="async"></div>`;
};

const layout = ({ title, description, path, content, crumbs, type='WebPage', noindex=false, record }) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · Tau Gamma Phi archive</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${abs(path)}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${abs(path)}"><meta name="theme-color" content="#0a0d10"><meta name="twitter:card" content="summary_large_image"><meta property="og:image" content="https://triskelion-de-zamboanga-digital-hub.vercel.app/src/assets/editorial/tau-gamma-phi-records-cover.webp"><meta property="og:type" content="${record?.eligibleForArticleSchema ? 'article' : type === 'CollectionPage' ? 'website' : 'article'}">${record?.cover ? `<meta property="og:image" content="${abs(record.cover.src)}"><meta name="twitter:card" content="summary_large_image">` : ''}${noindex ? '<meta name="robots" content="noindex,follow">' : ''}<link rel="stylesheet" href="/src/editorial/editorial.css"><link rel="stylesheet" href="/src/editorial/founders.css"><link rel="icon" href="/src/assets/brand/favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="32x32" href="/src/assets/brand/favicon-32.png"><link rel="apple-touch-icon" sizes="180x180" href="/src/assets/brand/seal-180.png">${schemas({ title, description, path, type:record?.eligibleForArticleSchema ? 'Article' : type, breadcrumbs: crumbs, record })}</head><body>${nav}<main class="editorial-main">${breadcrumb(crumbs)}${bannerFor(path)}${content}</main>${footer}</body></html>`;

// Hoisted slug helper: used by aliasPages, chapters, and history routes below.
const slugify = v => String(v).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70);
// Chapters can repeat an institution name across campuses (e.g. PMI Colleges
// in Quiapo and Marikina), so the slug includes location to stay unique.
const chapterSlug = r => slugify(`${r.institution} ${r.location || ''}`);
const card = record => `<article class="reading-card${record.cover ? ' reading-card-feature' : ''}">${record.cover ? `<img class="card-cover" src="${esc(record.cover.src)}" alt="${esc(record.cover.alt)}" loading="lazy">` : ''}<p class="kicker">${esc(record.section)}${record.pendingSources ? ' · Sources pending' : ''}</p><h2><a href="/stories/${esc(record.slug)}/">${esc(record.title)}</a></h2><p>${esc(record.description)}</p><a class="read-link" href="/stories/${esc(record.slug)}/">Read the full ${record.cover ? 'feature' : 'context'} <span aria-hidden="true">→</span></a></article>`;
const cite = text => esc(text).replace(/\[(\d+)\]/g, '<sup class="citation"><a href="#source-$1" aria-label="Go to source $1">[$1]</a></sup>');
const articleBody = record => record.body.map(part => `<section><h2>${esc(part.heading)}</h2>${part.paragraphs.map(p => `<p>${cite(p)}</p>`).join('')}</section>`).join('');
const estimateEvidence = record => record.estimateNotes?.length ? `<aside class="estimate-evidence" aria-label="Membership estimate evidence"><p class="kicker">ESTIMATE LABELS</p><h2>How to read the membership estimates</h2>${record.estimateNotes.map(note => `<div class="estimate-evidence-item"><p><strong>${esc(note.label)}</strong></p><p>${cite(note.text)} <span class="estimate-source-note">Source note ${cite(note.source)}</span></p></div>`).join('')}<p class="estimate-correction"><a class="read-link" href="${estimateCorrectionHref(record)}">Question this estimate?</a> <span>or</span> <a class="read-link" href="${estimateCorrectionHref(record)}">Suggest an evidence correction</a></p><p class="estimate-correction-note">Please identify the claim and include a public supporting reference. This opens your email client; it does not send automatically.</p></aside>` : '';
const estimateCorrectionHref = record => `mailto:hello@weforgeweb.com?subject=${encodeURIComponent(`Question this estimate: ${record.title}`)}&body=${encodeURIComponent(`Article: ${record.title} (${SEO_CONFIG.origin}/stories/${record.slug}/)\\n\\nPlease identify the estimate or claim you are questioning and provide a public supporting reference.`)}`;

const personalityCard = profile => `<article class="reading-card personality-card">${portraitMarkup(profile, 'personality-card-portrait')}<p class="kicker">${esc(profile.domain)} · ${profile.source ? 'Professional record linked' : 'Public record limited'}</p><h2><a href="/notable-triskelions/${esc(profile.id)}/">${esc(profile.name)}</a></h2><p>${esc(profile.summary)}</p><p class="personality-status">${profile.associationSource ? 'Association record linked separately' : 'Association remains unverified'}</p><a class="read-link" href="/notable-triskelions/${esc(profile.id)}/">View profile <span aria-hidden="true">→</span></a></article>`;
const personalitySchema = (profile, path) => `<script type="application/ld+json">${JSON.stringify({ '@context':'https://schema.org', '@type':'Person', name:profile.name, url:abs(path) })}</script>`;
// Section 13 shape: an editorial biography, not a resume. Each profile opens by
// explaining why the person belongs in the historical record, then separates a
// public life from a documented fraternity connection, lists milestones only
// where a date is actually supported, and points to related records.
// Nothing here infers membership from occupation or public office.
