const personalityPage = profile => {
  const path = `/notable-triskelions/${profile.id}/`;
  const professional = profile.source ? `<a href="${esc(profile.source.url)}" target="_blank" rel="noreferrer">${esc(profile.source.label)} ↗</a>` : '<span>Public professional source not attached.</span>';
  const association = profile.associationSource ? `<a href="${esc(profile.associationSource.url)}" target="_blank" rel="noreferrer">${esc(profile.associationSource.label)} ↗</a>` : '<span>Association record not attached; membership research pending; no official roster claim is made.</span>';
  const bio = personalityBio[profile.id] || {
    intro: `${profile.name} belongs in this record through a public contribution carried in the supplied research collection.`,
    beyond: 'The archive describes the public record available for this person and states clearly where it ends.',
    place: 'The fraternity connection is carried from the supplied research collection and is kept separate from the professional record.',
    milestones: [['Public record', 'Details are added only when a source supports them.']]
  };
  const milestones = bio.milestones.map(([when, what]) => `<div><dt>${esc(when)}</dt><dd>${esc(what)}</dd></div>`).join('');
  return layout({ title:profile.name, description:`A public biography of ${profile.name}, with professional achievements and Tau Gamma Phi association records kept distinct.`, path, crumbs:[{label:'Home',href:'/'},{label:'Notable Triskelions',href:'/notable-triskelions/'},{label:profile.name,href:path}], content:`<article class="reader personality-reader">${portraitMarkup(profile, 'personality-hero-portrait')}<p class="kicker">${esc(profile.domain)} · ${esc(profile.role)}</p><h1>${esc(profile.name)}</h1><p class="reader-dek">${esc(bio.intro)}</p><section><h2>A Life Beyond the Brotherhood</h2><p>${esc(bio.beyond)}</p></section><section><h2>Place in the Triskelion Story</h2><p>${esc(bio.place)}</p></section><section><h2>Milestones</h2><dl class="record-facts">${milestones}</dl></section><section><h2>Related Records</h2><p><a class="read-link" href="/notable-triskelions/">Meet More Notable Triskelions</a> <a class="read-link" href="/history/">Explore the National History</a> <a class="read-link" href="/councils/">Discover Councils</a> <a class="read-link" href="/chapters/">Explore Chapters</a> <a class="read-link" href="/videos/">Watch the Video Library</a></p></section><section><h2>Sources</h2><dl class="personality-evidence"><div><dt>Professional Record</dt><dd>${professional}</dd></div><div><dt>Association Record</dt><dd>${association}</dd></div></dl><p class="source-quality">The archive does not infer membership from occupation, public office, party-list naming, or association with another person. Professional achievement and fraternity association are separate records.</p><p><a class="read-link" href="mailto:hello@weforgeweb.com?subject=${encodeURIComponent(`Correction for personality profile: ${profile.name}`)}">Suggest a Source Correction ↗</a></p></section></article>${personalitySchema(profile,path)}` });
};

await rm('dist', { recursive:true, force:true });
await mkdir('dist', { recursive:true });
await cp('index.html', 'dist/index.html');
// Copy only runtime source and public design assets. Research inventories and
// rights registers under assets/ are intentionally excluded from the public build.
await cp('src', 'dist/src', { recursive:true });
await writeFile('dist/src/portrait-map.mjs', `// Generated from the approved portrait handoff; empty entries fall back to initials.\nexport const portraitMap = new Map(${JSON.stringify([...portraitMap])});\n`);
await cp('metadata.json', 'dist/metadata.json');
await mkdir('dist/news', { recursive:true });
await mkdir('dist/history', { recursive:true });
await mkdir('dist/references', { recursive:true });
await mkdir('dist/sitemap', { recursive:true });
await mkdir('dist/stories', { recursive:true });
await mkdir('dist/notable-triskelions', { recursive:true });

