  await mkdir(`dist${path}`, { recursive:true });
  await writeFile(`dist${path}index.html`, layout({ title, description:summary, path, crumbs:[{label:'Home',href:'/'},{label:'Videos',href:'/videos/'},{label:title,href:path}], content:`<article class="reader"><p class="kicker">${esc(platform)} · VIDEO LIBRARY</p><h1>${esc(title)}</h1><p class="reader-dek">${esc(summary)}</p><section><h2>About This Video</h2><p>This entry directs viewers to the original public source, where the publisher’s own context remains available. The archive does not re-upload the video or add an event date, transcript, council relationship, or other detail that the available material does not establish.</p></section><section><h2>Watch From the Original Source</h2><p><a class="read-link" href="${esc(sourceUrl)}" target="_blank" rel="noreferrer">Watch From the Original Source</a></p></section><section><h2>Connected to the Story</h2><p><a class="read-link" href="/history/">Explore the National History</a> <a class="read-link" href="/archive/videos/">Explore Videos in the Archive</a></p></section></article>` }));
