const catLabel = k => (chapterCategories.find(c => c.key === k) || {}).label || k;
for (const rec of chapterRecords) {
  const path = `/chapters/${chapterSlug(rec)}/`;
  await mkdir(`dist${path}`, { recursive: true });
  await writeFile(`dist${path}index.html`, layout({
    title: rec.institution,
    description: `Explore the Tau Gamma Phi chapter history associated with ${rec.institution} in ${rec.location}, including its recorded charter date and place in the wider story.`,
    path,
    crumbs: [{label:'Home',href:'/'},{label:'Chapters',href:'/chapters/'},{label:rec.institution,href:path}],
    content: `<article class="reader"><p class="kicker">${esc(catLabel(rec.category).toUpperCase())} CHAPTER</p><h1>${esc(rec.institution)}</h1><p class="reader-dek">${esc(rec.institution)} is recorded as a ${esc(catLabel(rec.category).toLowerCase())} chapter${rec.location ? ` in ${esc(rec.location)}` : ''}${rec.charterDate ? `, with a listed charter date of ${esc(rec.charterDate)}` : ''}. Its place in the wider Tau Gamma Phi story begins with that local setting.</p><section><h2>Chapter at a Glance</h2><dl class="record-facts"><div><dt>Institution or community</dt><dd>${esc(rec.institution)}</dd></div><div><dt>Charter date</dt><dd>${esc(rec.charterDate || 'Not recorded')}</dd></div><div><dt>Location</dt><dd>${esc(rec.location || 'Not recorded')}</dd></div><div><dt>District</dt><dd>${esc(rec.district || 'Not recorded')}</dd></div><dt>Chapter category</dt><dd>${esc(catLabel(rec.category))}</dd></div></dl></section><section><h2>Place in the Wider Story</h2><p>Chapter histories connect an institution or community to the councils, people, service, and milestones that developed around it. Additional local history, events, and preserved material can deepen this page when an authorized source is available.</p></section><section><h2>Sources and Historical Record</h2><p class="reader-note">${esc(publicCopy(chapterSourceNote))}</p><p><a class="read-link" href="${esc(chapterSource)}" target="_blank" rel="noreferrer">View the Listed Chapter Source</a></p></section><section><h2>Continue Exploring</h2><p><a class="read-link" href="/chapters/">Explore All Chapters</a> <a class="read-link" href="/councils/">Discover Councils</a> <a class="read-link" href="/history/">Follow the National History</a> <a class="read-link" href="/archive/">Enter the Digital Archive</a></p></section></article>`
  }));
}

// ==========================================
// National history decade pages (/history/{decade}/)
// Sourced from the approved timeline dataset in src/content.mjs.
// Hazing deaths and rivalry incidents are deliberately excluded.
// ==========================================
const decadeSlugs = [
  ['founding','Founding Context','Pre-1968 and the decision to build a different kind of fraternity at the University of the Philippines Diliman.','Where the Idea Took Shape','Students were already arguing about what a fraternity should be before there was one to join.'],
  ['1960s','The 1960s','The founding years at UP Diliman, including the October 4, 1968 establishment of the Triskelions’ Grand Fraternity.','A Fraternity Finds Its Name','The name changed more than once. The purpose held steady.'],
  ['1970s','The 1970s','Collegiate expansion across Metro Manila and Luzon and the emergence of an inter-chapter council structure.','From One Campus to Many','What started on a single campus began appearing across the city, and then across the island. As chapters multiplied, they needed a way to work together, and the council structure grew out of that need.'],
  ['1980s','The 1980s','Regional growth across the Visayas and Mindanao and the founding of the Triskelion Youth Movement.','Reaching the Visayas and Mindanao','The distance between chapters grew. So did the work of holding them together.'],
  ['1990s','The 1990s','Community chapters, the alumni organization, and organized service work.','Community Chapters and the Alumni Organization','Members who left school did not leave the brotherhood. Community chapters and an alumni organization gave that continued belonging a structure of its own.'],
  ['2000s','The 2000s','International and diaspora councils connecting Filipino Triskelions abroad.','Triskelions Across the World','Filipino members carried the fraternity with them. The history of this period is also a history of migration.'],
  ['2010s','The 2010s','Organizational development and the legal context set by Republic Act No. 11053.','New Rules for a New Era','Republic Act No. 11053 changed the legal ground under every fraternity in the country. This archive states that boundary plainly and points readers to the law itself.'],
  ['2020s','The 2020s','Digital preservation, documentation, and public source access.','Keeping the Record for the Next Generation','Preservation is slower and less visible than founding. It is also how the earlier decades survive.']
];
const decadeFor = slug => {
  const byEra = {
    founding: 'Before 1968', '1960s': '1968', '1970s': '1970s', '1980s': '1980s',
    '1990s': '1990s', '2000s': '2000s', '2010s': '2010s', '2020s': '2020s & Present'
  };
  const era = byEra[slug];
  return content.historicalTimeline.find(t => t.era === era);
};
for (const [slug, label, blurb, periodHeading, periodNote] of decadeSlugs) {
  const rec = decadeFor(slug);
  const body = rec
    ? `<p>${esc(rec.description)}</p><p>${esc(periodNote)}</p><p class="reader-note">Sources and historical record: ${esc(publicCopy(rec.verification))}. The references linked from the national history preserve the basis for this period.</p>`
    : `<p>${esc(blurb)}</p><p class="reader-note">This period is introduced from the available historical record. Related sources are kept with the national history.</p>`;
  const path = `/history/${slug}/`;
  await mkdir(`dist${path}`, { recursive: true });
  await writeFile(`dist${path}index.html`, layout({
    title: label,
    description: blurb,
    path,
    crumbs: [{label:'Home',href:'/'},{label:'History',href:'/history/'},{label:label,href:path}],
    content: `<article class="reader"><p class="kicker">NATIONAL HISTORY</p><h1>${esc(label)}</h1><p class="reader-dek">${esc(blurb)}</p><section><h2>${esc(periodHeading)}</h2>${body}</section><section><h2>Continue Exploring</h2><p><a class="read-link" href="/founding-fathers/">Meet the Founding Generation</a> <a class="read-link" href="/councils/">Explore Councils</a> <a class="read-link" href="/history/">Follow the National Timeline</a> <a class="read-link" href="/sources/">Read the Sources and Historical Record</a></p></section></article>`
  }));
}


